using UnityEngine;
namespace ValheimMastery{internal static class MasterIdolResidentDiagnostics{
internal static string Describe(Character actor){if(actor==null)return "friend actor=none";var data=actor.m_nview?.GetZDO();bool actual=data!=null&&ReferenceEquals(ZDOMan.instance?.GetZDO(data.m_uid),data);var home=MasterIdolResidentPolicy.TryHome(actor,out var zone);string reason=!GoldCraftingService.Enabled?"perk-disabled":actor.IsDead()?"dead":actor.m_nview?.IsValid()!=true?"view-invalid":!actual?"stale-ZDO":!MasterIdolEffectZones.Ready?"projection-unready":!home?"not-in-active-roster":"active-roster";var player=Player.m_localPlayer;return "nativeTamed="+actor.IsTamed()+" permanentFriend="+MasterIdolNativeTaming.Friend(actor)+" friend proof="+reason+" homeHint="+(data?.GetString("vm.idol.home.v1","")??"")+" welcomed="+(data?.GetBool("vm.idol.welcomed.v1",false)??false)+" actorInside="+(zone?.Contains(actor.transform.position)??false)+" playerFriendly="+(player!=null&&MasterIdolResidentPolicy.Friendly(actor,player))+" playerWardAccess="+(player!=null&&MasterIdolEffectZones.Allows(player.GetPlayerID(),player.transform.position))+" "+MasterIdolEffectZones.Diagnostics();}
}}
